      };

      expect(() => createSchemaCompiler(engine).compile(schema))
        .toThrow(/keyword "id".*\$id/);
      expect(() => validateSchemaCollection([schema], engine))
        .toThrow(/keyword "id".*\$id/);
    },
  );

